import{_ as e,o as t,c as r,e as s}from"./app.44093d4a.js";const n={},o=s('<h1 id="\u{1F4DD}-\u82F1\u8BED\u9AD8\u9891-\u8138\u76F2-\u8BCD\u6C47\u5168\u901A\u5173-deserve-\u53CA\u5176\u76F8\u4F3C\u8BCD\u5168\u9762\u89E3\u6790" tabindex="-1"><a class="header-anchor" href="#\u{1F4DD}-\u82F1\u8BED\u9AD8\u9891-\u8138\u76F2-\u8BCD\u6C47\u5168\u901A\u5173-deserve-\u53CA\u5176\u76F8\u4F3C\u8BCD\u5168\u9762\u89E3\u6790" aria-hidden="true">#</a> \u{1F4DD} \u82F1\u8BED\u9AD8\u9891\u201C\u8138\u76F2\u201D\u8BCD\u6C47\u5168\u901A\u5173\uFF1ADeserve \u53CA\u5176\u76F8\u4F3C\u8BCD\u5168\u9762\u89E3\u6790</h1><h2 id="\u{1F4CC}-\u6838\u5FC3\u8BCD\u6C47" tabindex="-1"><a class="header-anchor" href="#\u{1F4CC}-\u6838\u5FC3\u8BCD\u6C47" aria-hidden="true">#</a> \u{1F4CC} \u6838\u5FC3\u8BCD\u6C47</h2><ul><li><strong>Deserve</strong> /d\u026A\u02C8z\u025C\u02D0rv/ <ul><li><strong>\u8BCD\u6027</strong>\uFF1A\u52A8\u8BCD (vt.)</li><li><strong>\u91CA\u4E49</strong>\uFF1A\u503C\u5F97\u3001\u5E94\u53D7</li><li><strong>\u6838\u5FC3\u8BB0\u5FC6\u70B9</strong>\uFF1A\u5E26\u5B57\u6BCD <strong>v</strong>\uFF0C\u8054\u60F3 <strong>V</strong>alue\uFF08\u4EF7\u503C\uFF09 \u27A1\uFE0F \u6709\u4EF7\u503C\u624D<strong>\u503C\u5F97</strong>\u3002</li></ul></li></ul><hr><h2 id="\u{1F50D}-\u7B2C\u4E00\u7EC4-\u5B57\u6BCD\u4EC5\u5DEE\u4E00\u4E2A\u7684-\u7EC8\u6781\u53D8\u5F62\u602A-deserve-vs-desert-vs-dessert" tabindex="-1"><a class="header-anchor" href="#\u{1F50D}-\u7B2C\u4E00\u7EC4-\u5B57\u6BCD\u4EC5\u5DEE\u4E00\u4E2A\u7684-\u7EC8\u6781\u53D8\u5F62\u602A-deserve-vs-desert-vs-dessert" aria-hidden="true">#</a> \u{1F50D} \u7B2C\u4E00\u7EC4\uFF1A\u5B57\u6BCD\u4EC5\u5DEE\u4E00\u4E2A\u7684\u201C\u7EC8\u6781\u53D8\u5F62\u602A\u201D (Deserve vs Desert vs Dessert)</h2><p>\u8FD9\u4E09\u4E2A\u8BCD\u662F\u65E5\u5E38\u9605\u8BFB\u548C\u8003\u8BD5\u4E2D\u6700\u5BB9\u6613\u6DF7\u6DC6\u7684\u201C\u4E09\u5251\u5BA2\u201D\uFF1A</p><table><thead><tr><th style="text-align:left;">\u5355\u8BCD</th><th style="text-align:left;">\u97F3\u6807</th><th style="text-align:left;">\u8BCD\u6027 &amp; \u91CA\u4E49</th><th style="text-align:left;">\u72EC\u5BB6\u901F\u8BB0\u6CD5</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Deserve</strong></td><td style="text-align:left;">/d\u026A\u02C8z\u025C\u02D0rv/</td><td style="text-align:left;">v. \u503C\u5F97\uFF0C\u5E94\u5F97</td><td style="text-align:left;">\u542B\u6709 <strong>v</strong> \u27A1\uFE0F <strong>V</strong>alue (\u4EF7\u503C) \u27A1\uFE0F \u503C\u5F97</td></tr><tr><td style="text-align:left;"><strong>Desert</strong></td><td style="text-align:left;">/\u02C8dez\u0259rt/<br>/d\u026A\u02C8z\u025C\u02D0rt/</td><td style="text-align:left;">n. \u6C99\u6F20<br>v. \u629B\u5F03\uFF0C\u64C5\u79BB\u804C\u5B88</td><td style="text-align:left;">\u53EA\u6709 <strong>1\u4E2A s</strong> \u27A1\uFE0F <strong>S</strong>and (\u6C99\u5B50) \u27A1\uFE0F \u6C99\u6F20\uFF1B<br>\u591A\u4E86\u4E00\u4E2A\u4EBA\u5C31\u60F3<strong>\u629B\u5F03</strong>\u4ED6</td></tr><tr><td style="text-align:left;"><strong>Dessert</strong></td><td style="text-align:left;">/d\u026A\u02C8z\u025C\u02D0rt/</td><td style="text-align:left;">n. \u751C\u70B9</td><td style="text-align:left;">\u6709 <strong>2\u4E2A s</strong> \u27A1\uFE0F <strong>S</strong>weet <strong>S</strong>nack (\u751C\u70B9) \u27A1\uFE0F \u597D\u5403\u7684\u751C\u70B9\u60F3\u5403<strong>\u53CC\u4EFD</strong></td></tr></tbody></table><blockquote><p>\u{1F4A1} <strong>\u542C\u529B\u5927\u5751</strong>\uFF1A\u5F53 <strong>Desert</strong> \u4F5C\u52A8\u8BCD\uFF08\u629B\u5F03\uFF09\u65F6\uFF0C\u5176\u53D1\u97F3\u4E0E <strong>Dessert</strong>\uFF08\u751C\u70B9\uFF09<strong>\u5B8C\u5168\u76F8\u540C</strong> /d\u026A\u02C8z\u025C\u02D0rt/\uFF0C\u5FC5\u987B\u901A\u8FC7\u4E0A\u4E0B\u6587\u8BED\u5883\u533A\u5206\uFF01</p></blockquote><hr><h2 id="\u{1F441}\uFE0F-\u7B2C\u4E8C\u7EC4-\u89C6\u89C9\u626B\u63CF\u9677\u9631-de-\u5F00\u5934-e-\u7ED3\u5C3E-\u957F\u5EA6\u6781\u8FD1" tabindex="-1"><a class="header-anchor" href="#\u{1F441}\uFE0F-\u7B2C\u4E8C\u7EC4-\u89C6\u89C9\u626B\u63CF\u9677\u9631-de-\u5F00\u5934-e-\u7ED3\u5C3E-\u957F\u5EA6\u6781\u8FD1" aria-hidden="true">#</a> \u{1F441}\uFE0F \u7B2C\u4E8C\u7EC4\uFF1A\u89C6\u89C9\u626B\u63CF\u9677\u9631\uFF08de- \u5F00\u5934\uFF0C-e \u7ED3\u5C3E\uFF0C\u957F\u5EA6\u6781\u8FD1\uFF09</h2><p>\u8FD9\u7EC4\u8BCD\u5728\u5FEB\u901F\u9605\u8BFB\u4E2D\u6781\u6613\u770B\u9519\uFF0C\u5C5E\u4E8E\u201C\u9AA8\u67B6\u201D\u6781\u5176\u76F8\u4F3C\u7684\u8BCD\u6C47\uFF1A</p><ul><li><strong>Desire</strong> /d\u026A\u02C8za\u026A\u0259r/ <em>(v./n. \u6E34\u671B\uFF0C\u6B32\u671B)</em><ul><li><em>\u8FA8\u6790</em>\uFF1A\u6BD4 deserve \u5C11\u4E86\u5B57\u6BCD v\uFF0C\u591A\u4E86\u4E00\u4EFD\u5185\u5FC3\u7684\u6E34\u671B\u3002</li></ul></li><li><strong>Deceive</strong> /d\u026A\u02C8si\u02D0v/ <em>(v. \u6B3A\u9A97)</em><ul><li><em>\u8FA8\u6790</em>\uFF1A\u540C\u6837\u662F <code>de-</code> \u5F00\u5934 <code>-ve</code> \u7ED3\u5C3E\uFF0C\u4E2D\u95F4\u662F <code>cei</code>\u3002</li></ul></li><li><strong>Deprive</strong> /d\u026A\u02C8pra\u026Av/ <em>(v. \u5265\u593A\uFF0C\u4F7F\u4E27\u5931)</em><ul><li><em>\u8FA8\u6790</em>\uFF1A\u7ED3\u6784\u5B8C\u5168\u4E00\u81F4\uFF08de + \u8F85\u97F3 + r + \u8F85\u97F3 + e\uFF09\u3002\u5E38\u7528\u4E8E\u642D\u914D\uFF1A<code>deprive sb of sth</code>\u3002</li></ul></li><li><strong>Despise</strong> /d\u026A\u02C8spa\u026Az/ <em>(v. \u9119\u89C6\uFF0C\u770B\u4E0D\u8D77)</em><ul><li><em>\u8FA8\u6790</em>\uFF1A\u957F\u5EA6\u76F8\u540C\uFF0C\u9996\u5C3E\u76F8\u540C\uFF0C\u4E2D\u95F4\u90FD\u6709\u5B57\u6BCD s\u3002</li></ul></li><li><strong>Despair</strong> /d\u026A\u02C8sp\u025B\u0259r/ <em>(v./n. \u7EDD\u671B)</em><ul><li><em>\u8FA8\u6790</em>\uFF1A\u540C\u6837\u662F <code>des-</code> \u5F00\u5934\uFF0C\u540E\u534A\u90E8\u5206\u62FC\u5199\u6613\u6DF7\u3002</li></ul></li><li><strong>Derived</strong> /d\u026A\u02C8ra\u026Avd/ <em>(v. \u6E90\u81EA\uFF0C\u884D\u751F - \u8FC7\u53BB\u5F0F/\u5F62\u5BB9\u8BCD)</em><ul><li><em>\u8FA8\u6790</em>\uFF1A\u628A deserve \u7684 <code>s</code> \u6362\u6210\u4E86 <code>r</code>\uFF0C\u89C6\u89C9\u4E0A\u975E\u5E38\u76F8\u50CF\u3002</li></ul></li></ul><hr><h2 id="\u{1F6E1}\uFE0F-\u7B2C\u4E09\u7EC4-\u8BCD\u5C3E\u76F8\u540C\u5F62\u4F3C\u8BCD-serve-\u7CFB\u5217\u53CA\u5176\u4ED6" tabindex="-1"><a class="header-anchor" href="#\u{1F6E1}\uFE0F-\u7B2C\u4E09\u7EC4-\u8BCD\u5C3E\u76F8\u540C\u5F62\u4F3C\u8BCD-serve-\u7CFB\u5217\u53CA\u5176\u4ED6" aria-hidden="true">#</a> \u{1F6E1}\uFE0F \u7B2C\u4E09\u7EC4\uFF1A\u8BCD\u5C3E\u76F8\u540C\u5F62\u4F3C\u8BCD\uFF08-serve \u7CFB\u5217\u53CA\u5176\u4ED6\uFF09</h2><p>\u8FD9\u7EC4\u8BCD\u4E3B\u8981\u5BB9\u6613\u5728\u5FEB\u901F\u626B\u89C6\u65F6\uFF0C\u56E0\u4E3A\u76F8\u540C\u7684\u8BCD\u5C3E\u6216\u8BCD\u5934\u800C\u4EA7\u751F\u89C6\u89C9\u9519\u89C9\uFF1A</p><ul><li><strong>Reserve</strong> /r\u026A\u02C8z\u025C\u02D0rv/ <em>(v. \u9884\u8BA2\u3001\u4FDD\u7559)</em>\uFF1A\u62FC\u5199\u4EC5\u76F8\u5DEE\u4E00\u4E2A\u9996\u5B57\u6BCD\uFF08<code>de-</code> \u6362\u6210\u4E86 <code>re-</code>\uFF09\u3002</li><li><strong>Observe</strong> /\u0259b\u02C8z\u025C\u02D0rv/ <em>(v. \u89C2\u5BDF\u3001\u9075\u5B88)</em>\uFF1A\u7ED3\u5C3E\u540C\u6837\u662F <code>-serve</code>\u3002</li><li><strong>Preserve</strong> /pr\u026A\u02C8z\u025C\u02D0rv/ <em>(v. \u4FDD\u62A4\u3001\u4FDD\u5B58)</em>\uFF1A\u540C\u6837\u662F\u4EE5 <code>-serve</code> \u7ED3\u5C3E\u7684\u5E38\u89C1\u8BCD\u3002</li><li><strong>Design</strong> /d\u026A\u02C8za\u026An/ <em>(v./n. \u8BBE\u8BA1)</em>\uFF1A\u9996\u5C3E\u5B57\u6BCD\u76F8\u540C\uFF0C\u957F\u5EA6\u76F8\u8FD1\u3002</li></ul><hr><h2 id="\u{1F9E0}-\u7B2C\u56DB\u7EC4-\u610F\u4E49\u76F8\u8FD1\u7684-\u540C\u4E49\u66FF\u6362\u8BCD-\u907F\u514D\u8BB0\u6DF7" tabindex="-1"><a class="header-anchor" href="#\u{1F9E0}-\u7B2C\u56DB\u7EC4-\u610F\u4E49\u76F8\u8FD1\u7684-\u540C\u4E49\u66FF\u6362\u8BCD-\u907F\u514D\u8BB0\u6DF7" aria-hidden="true">#</a> \u{1F9E0} \u7B2C\u56DB\u7EC4\uFF1A\u610F\u4E49\u76F8\u8FD1\u7684\u201C\u540C\u4E49\u66FF\u6362\u8BCD\u201D\uFF08\u907F\u514D\u8BB0\u6DF7\uFF09</h2><p>\u8FD9\u51E0\u4E2A\u8BCD\u5728\u8868\u8FBE\u201C\u5E94\u8BE5\u5F97\u5230/\u503C\u5F97\u201D\u65F6\u610F\u601D\u76F8\u8FD1\uFF0C\u5728\u80CC\u8BF5\u6216\u5199\u4F5C\u66FF\u6362\u65F6\u7ECF\u5E38\u4E32\u95E8\uFF1A</p><ul><li><strong>Merit</strong>\uFF1A\u610F\u4E3A\u201C\u503C\u5F97\u3001\u5E94\u53D7\u201D\uFF0C\u5C5E\u4E8E\u6700\u6807\u51C6\u7684\u540C\u4E49\u66FF\u6362\u8BCD\u4E4B\u4E00\u3002</li><li><strong>Earn</strong>\uFF1A\u610F\u4E3A\u201C\u8D5A\u5F97\u3001\u8D62\u5F97\u201D\uFF0C\u4FA7\u91CD\u4E8E\u901A\u8FC7\u52AA\u529B\u4ED8\u51FA\u800C\u201C\u5E94\u5F97\u201D\u67D0\u7269\u3002</li><li><strong>Rate</strong>\uFF1A\u5728\u7279\u5B9A\u8BED\u5883\u4E0B\u610F\u4E3A\u201C\u88AB\u8BA4\u4E3A\u503C\u5F97\u3001\u5E94\u5F97\u201D\u3002</li><li><strong>Warrant</strong>\uFF1A\u610F\u4E3A\u201C\u503C\u5F97\u3001\u4F7F\u2026\u2026\u663E\u5F97\u6B63\u5F53\u201D\uFF0C\u5E38\u7528\u4E8E\u5F3A\u8C03\u67D0\u4E8B\u662F\u5E94\u5F97\u7684\u52A8\u4F5C\u6216\u7ED3\u679C\u3002</li><li><strong>Be worthy of</strong>\uFF1A\u8BCD\u7EC4\uFF0C\u610F\u4E3A\u201C\u914D\u5F97\u4E0A\u3001\u503C\u5F97\u201D\u3002</li></ul><hr><h2 id="\u{1F3AC}-\u6545\u4E8B\u753B\u9762\u4E32\u8BB0\u6CD5-\u4E00\u53E5\u8BDD\u8BB0\u4F4F-5-\u4E2A\u5730\u72F1\u7EA7\u8138\u76F2\u8BCD" tabindex="-1"><a class="header-anchor" href="#\u{1F3AC}-\u6545\u4E8B\u753B\u9762\u4E32\u8BB0\u6CD5-\u4E00\u53E5\u8BDD\u8BB0\u4F4F-5-\u4E2A\u5730\u72F1\u7EA7\u8138\u76F2\u8BCD" aria-hidden="true">#</a> \u{1F3AC} \u6545\u4E8B\u753B\u9762\u4E32\u8BB0\u6CD5\uFF08\u4E00\u53E5\u8BDD\u8BB0\u4F4F 5 \u4E2A\u5730\u72F1\u7EA7\u8138\u76F2\u8BCD\uFF09</h2><blockquote><p><strong>\u6545\u4E8B\u7EBF</strong>\uFF1A\u4E00\u4E2A\u5728<strong>\u6C99\u6F20</strong>\u4E2D\u6781\u5EA6<strong>\u6E34\u671B</strong>\u5403<strong>\u751C\u70B9</strong>\u7684\u4EBA\uFF0C<strong>\u503C\u5F97</strong>\u88AB\u540C\u60C5\uFF0C\u800C\u4E0D\u662F\u88AB<strong>\u629B\u5F03</strong>\u3002</p></blockquote><ul><li><strong>\u82F1\u6587</strong>\uFF1AHe does not <strong>deserve</strong> to be <strong>deserted</strong> in the <strong>desert</strong> just because of his <strong>desire</strong> for <strong>dessert</strong>.</li><li><strong>\u4E2D\u6587</strong>\uFF1A\u4ED6\u4E0D\u80FD\u4EC5\u4EC5\u56E0\u4E3A<strong>\u6E34\u671B</strong>\u5403<strong>\u751C\u70B9</strong>\uFF0C\u5C31<strong>\u503C\u5F97</strong>\u88AB<strong>\u629B\u5F03</strong>\u5728<strong>\u6C99\u6F20</strong>\u91CC\u3002</li></ul>',24),l=[o];function d(g,i){return t(),r("div",null,l)}var h=e(n,[["render",d],["__file","index.html.vue"]]);export{h as default};
